    ],
  },
  {
    name: 'Vault Approach',
    hint: 'Three guards guard the vault door. Patience wins.',
    grid: [
      '########################',
      '#......C.......#.......#',
      '#..S...C.......#.......#',
      '#......C.......#.......#',
      '#..............#...CC..#',
